const showToast = (message,type='success') => {const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toastRegion').append(el);setTimeout(()=>el.remove(),3600)};
const configFromInputs = () => ({apiKey:$('#fbApiKey').value.trim(),authDomain:$('#fbAuthDomain').value.trim(),projectId:$('#fbProjectId').value.trim(),appId:$('#fbAppId').value.trim()});
const validConfig = c => !!(c?.apiKey && c?.authDomain && c?.projectId && c?.appId);
const getSavedFirebaseConfig = () => {try{return JSON.parse(localStorage.getItem('fbtq_firebase_config')||'null')}catch{return null}};

async function firebaseInit(config, announce=false) {
  if (!validConfig(config)) return false;
  if(state.firebase){if(announce)showToast('Firebase đã kết nối trong phiên này. Tải lại trang để thay đổi dự án.');return true}
  try {
    const [appMod,authMod,storeMod,funcMod] = await Promise.all([
      import('https://www.gstatic.com/firebasejs/10.14.1/firebase-app.js'),
      import('https://www.gstatic.com/firebasejs/10.14.1/firebase-auth.js'),
      import('https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore.js'),
      import('https://www.gstatic.com/firebasejs/10.14.1/firebase-functions.js')
    ]);
    const app = appMod.getApps().length ? appMod.getApp() : appMod.initializeApp(config);
    const auth = authMod.getAuth(app);
    const db = storeMod.getFirestore(app);
    const functions = funcMod.getFunctions(app);
    state.firebase = {app,auth,db,functions,authMod,storeMod,funcMod};
    $('#firebaseIndicator').textContent='● Firebase đã kết nối';$('#firebaseIndicator').classList.add('connected');$('#firebaseStatus').textContent='● Firebase đã kết nối';$('#firebaseStatus').className='status status-live';
    authMod.onAuthStateChanged(auth, async user => {
      if (!user) { if (state.user?.uid) signOutToAuth(); return; }
      if(state.signingUp)return;
      try {
        const userRef=storeMod.doc(db,'users',user.uid);
        const snap=await storeMod.getDoc(userRef);
        let profile=snap.exists()?snap.data():null;
        if(!profile){
          profile={name:user.displayName||user.email||'Nhân viên',email:user.email||'',role:'employee',approved:true};
          await storeMod.setDoc(userRef,{...profile,createdAt:storeMod.serverTimestamp()});
        }
        const token=await user.getIdTokenResult();
        state.user={uid:user.uid,email:user.email,name:profile.name||user.displayName||user.email,role:profile.role||token.claims.role||'employee',approved:true};state.role=state.user.role;enterApp();
      } catch(e){console.error(e);showToast('Không tạo hoặc đọc được hồ sơ. Hãy cập nhật Firestore Rules mới.','error')}
    });
    if(announce)showToast('Đã kết nối Firebase. Bật Email/Password và triển khai Firestore Rules.');
    return true;
  } catch(error) {
    console.error(error);if(announce)showToast('Không kết nối được Firebase: '+(error.message||'kiểm tra cấu hình và hosting HTTPS'),'error');return false;
  }
}
async function saveRecord(collection,data,id=crypto.randomUUID()) {
  if(!state.firebase)return id;
  const {db,storeMod}=state.firebase;
  await storeMod.setDoc(storeMod.doc(db,'workspaces','fbtq',collection,id),{...data,updatedAt:storeMod.serverTimestamp(),updatedBy:state.user?.uid||null,createdBy:data.createdBy||state.user?.uid||null},{merge:true});
  return id;
}
async function callFunction(name,data) {
  if(!state.firebase)throw new Error('Kết nối Firebase trước khi dùng dịch vụ AI thật.');
  const callable=state.firebase.funcMod.httpsCallable(state.firebase.functions,name);
  const result=await callable(data);return result.data;
}
function signOutToAuth(){if(state.inboxUnsubscribe){state.inboxUnsubscribe();state.inboxUnsubscribe=null}if(state.messageUnsubscribe){state.messageUnsubscribe();state.messageUnsubscribe=null}state.user=null;state.role='employee';localStorage.removeItem('fbtq_demo_user');$('#app').classList.add('hidden');$('#authScreen').classList.remove('hidden')}
function enterApp(){
  loadLocalForUser();
  $('#authScreen').classList.add('hidden');$('#app').classList.remove('hidden');
  const name=state.user?.name||'Minh Anh', initials=name.split(/\s+/).filter(Boolean).slice(-2).map(x=>x[0]).join('').toUpperCase()||'MA';
  $('#sideUserName').textContent=name;$('#greetingName').textContent=name.split(/\s+/)[0];$('#sideUserRole').textContent=roleName(state.role);$('#sideAvatar').textContent=initials;$('#topAvatar').textContent=initials;
  $$('.admin-only').forEach(el=>el.classList.toggle('hidden',!isDirector()));$$('.manager-only').forEach(el=>el.classList.toggle('hidden',!isManager()));
  $('#taskPermissionHint').classList.toggle('hidden',isManager());$('#taskNavCount').textContent=state.tasks.filter(t=>t.status!=='done').length;
  renderTasks();renderMetrics();renderDrafts();saveLocal();
  if(state.firebase && state.user?.uid!=='demo')loadCloudData();
}
async function loadCloudData(){try{const {db,storeMod}=state.firebase;const ref=name=>storeMod.collection(db,'workspaces','fbtq',name);const taskQuery=isManager()?ref('tasks'):storeMod.query(ref('tasks'),storeMod.where('assigneeUid','==',state.user.uid));const draftQuery=isManager()?ref('drafts'):storeMod.query(ref('drafts'),storeMod.where('createdBy','==',state.user.uid));const templateQuery=isManager()?ref('contentTemplates'):storeMod.query(ref('contentTemplates'),storeMod.where('status','==','approved'));const inboxQuery=storeMod.query(ref('inbox'),storeMod.where('ownerUid','==',state.user.uid));const messageQuery=storeMod.query(ref('messages'),storeMod.where('ownerUid','==',state.user.uid));const requests=[storeMod.getDocs(taskQuery),storeMod.getDocs(ref('campaigns')),storeMod.getDocs(draftQuery),storeMod.getDocs(templateQuery),storeMod.getDocs(inboxQuery),storeMod.getDocs(messageQuery)];if(isManager()){requests.push(storeMod.getDocs(ref('contentReviews')));requests.push(storeMod.getDocs(storeMod.collection(db,'users')))}const snaps=await Promise.all(requests);state.tasks=snaps[0].docs.map(d=>({id:d.id,...d.data()}));state.metrics=snaps[1].docs.map(d=>({id:d.id,...d.data()}));state.drafts=snaps[2].docs.map(d=>({id:d.id,...d.data()}));state.templates=snaps[3].docs.map(d=>({id:d.id,...d.data()}));state.inboxThreads=snaps[4].docs.map(d=>({id:d.id,...d.data()}));state.messages=snaps[5].docs.map(d=>({id:d.id,...d.data()}));const botSnap=await storeMod.getDoc(storeMod.doc(db,'workspaces','fbtq','settings','bot'));if(botSnap.exists()){const bot=botSnap.data();if(bot.scripts)state.scripts=bot.scripts;if(bot.banned)state.banned=bot.banned;if(bot.brandVoice)$('#brandVoice').value=bot.brandVoice;if(bot.defaultModel){$('#defaultModel').value=bot.defaultModel;const radio=$(`input[name="aiModel"][value="${bot.defaultModel}"]`);if(radio){radio.checked=true;$$('.model-choice').forEach(x=>x.classList.toggle('selected',$('input',x)===radio))}}}if(isManager()&&snaps[6])state.reviews=snaps[6].docs.map(d=>({id:d.id,...d.data()}));if(isManager()&&snaps[7])state.members=snaps[7].docs.map(d=>({uid:d.id,...d.data()})).filter(m=>m.approved).map(m=>({uid:m.uid,name:m.name||m.email,initials:(m.name||m.email||'??').split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase(),tone:'blue'}));const assignee=$('#taskAssigneeFilter');assignee.innerHTML='<option value="all">Tất cả nhân viên</option>'+state.members.map(m=>`<option value="${esc(m.name)}">${esc(m.name)}</option>`).join('');saveLocal();renderTasks();renderMetrics();renderDrafts();renderInbox();if(state.inboxUnsubscribe)state.inboxUnsubscribe();if(state.messageUnsubscribe)state.messageUnsubscribe();state.inboxUnsubscribe=storeMod.onSnapshot(inboxQuery,snapshot=>{state.inboxThreads=snapshot.docs.map(d=>({id:d.id,...d.data()}));renderInbox()});state.messageUnsubscribe=storeMod.onSnapshot(messageQuery,snapshot=>{state.messages=snapshot.docs.map(d=>({id:d.id,...d.data()}));if(state.activeThread)selectThread(state.activeThread)});$('#taskNavCount').textContent=state.tasks.filter(t=>t.status!=='done').length}catch(e){console.error(e);showToast('Không tải được dữ liệu. Kiểm tra Firestore Rules.','error')}}
function renderInbox(){const list=$('.inbox-list');if(!list)return;$$('.conversation',list).forEach(el=>el.remove());if(!state.inboxThreads.length){state.activeThread=null;list.insertAdjacentHTML('beforeend','<div class="conversation"><span class="avatar avatar-blue">✦</span><div><div class="conversation-head"><b>Chưa có hội thoại</b></div><p>Kết nối Fanpage để nhận tin nhắn.</p><span class="channel-tag">Webhook chưa nhận dữ liệu</span></div></div>');$('#chatBody').innerHTML='<div class="result-empty"><h3>Chưa có tin nhắn</h3><p>Kết nối Fanpage và đăng ký webhook để hiển thị hội thoại thật tại đây.</p></div>';return}state.inboxThreads.sort((a,b)=>(b.receivedAt?.seconds||0)-(a.receivedAt?.seconds||0));state.inboxThreads.forEach((thread,index)=>{const name=thread.senderName||`Khách ${String(thread.senderId||'').slice(-4)}`;const row=document.createElement('div');row.className='conversation'+(index===0?' selected':'');row.dataset.threadId=thread.id;row.innerHTML=`<span class="avatar avatar-lilac">${esc(name.split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase())}</span><div><div class="conversation-head"><b>${esc(name)}</b><small>${thread.receivedAt?.seconds?new Date(thread.receivedAt.seconds*1000).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}):''}</small></div><p>${esc(thread.message||'[Tệp đính kèm]')}</p><span class="channel-tag">FB · ${esc(thread.pageName||'Fanpage')}</span></div>`;row.addEventListener('click',()=>selectThread(thread));list.append(row)});selectThread(state.inboxThreads[0])}
function selectThread(thread){state.activeThread=thread;$$('.conversation').forEach(el=>el.classList.toggle('selected',el.dataset.threadId===thread.id));const name=thread.senderName||`Khách ${String(thread.senderId||'').slice(-4)}`;const header=$('.chat-header');$('.avatar',header).textContent=name.split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase();$('div:nth-child(2) b',header).textContent=name;$('div:nth-child(2) small',header).textContent=`Messenger · ${thread.pageName||'Fanpage'}`;const history=state.messages.filter(m=>m.conversationId===thread.conversationId).sort((a,b)=>(a.createdAt?.seconds||0)-(b.createdAt?.seconds||0));const latestIncoming=[...history].reverse().find(m=>m.direction==='incoming');state.activeMessage=latestIncoming?.message||thread.message;const items=history.length?history:[thread];const bubbles=items.map(m=>{const time=m.createdAt?.seconds?new Date(m.createdAt.seconds*1000).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}):'';return`<div class="message ${m.direction==='outgoing'?'our-message':'customer-msg'}">${esc(m.message||'[Tệp đính kèm]')}<small>${time}</small></div>`}).join('');$('#chatBody').innerHTML=`<div class="chat-date">${thread.receivedAt?.seconds?new Date(thread.receivedAt.seconds*1000).toLocaleDateString('vi-VN',{day:'2-digit',month:'long'}):'Hội thoại'}</div>${bubbles}${latestIncoming?`<div class="ai-suggestion"><div><span class="ai-spark">✦</span><b>Gợi ý trả lời từ AI</b><span class="suggestion-model">${esc(thread.model||'Gemini')}</span></div><p>Chọn “Tạo gợi ý” để AI soạn câu trả lời theo kịch bản đã duyệt.</p><div class="suggestion-actions"><button id="sendSuggestion">✓ Gửi trả lời</button><button id="editSuggestion">✎ Chỉnh sửa</button><button class="regenerate" id="regenerateReply">↻ Tạo gợi ý</button></div></div>`:''}`;bindChatActions();}
function bindChatActions(){const suggest=$('#regenerateReply');suggest?.addEventListener('click',async()=>{if(!state.firebase||!state.activeThread)return showToast('Kết nối Fanpage và Firebase để tạo gợi ý thật.','error');suggest.disabled=true;suggest.textContent='Đang tạo…';try{const result=await callFunction('suggestReply',{pageId:state.activeThread.pageId,message:state.activeMessage,model:state.activeThread.model||'gemini'});$('.ai-suggestion p').textContent=result.content}catch(e){showToast(e.message,'error')}finally{suggest.disabled=false;suggest.textContent='↻ Tạo lại'}});$('#sendSuggestion')?.addEventListener('click',async()=>{const text=$('.ai-suggestion p').textContent;if(text.startsWith('Chọn “Tạo gợi ý”'))return showToast('Tạo gợi ý trước khi gửi.','error');await sendChatReply(text)});$('#editSuggestion')?.addEventListener('click',()=>{const p=$('.ai-suggestion p');p.contentEditable='true';p.focus()})}
async function sendChatReply(text){if(state.firebase){if(!state.activeThread)return showToast('Chưa có hội thoại Fanpage để trả lời.','error');try{await callFunction('sendPageReply',{pageId:state.activeThread.pageId,recipientId:state.activeThread.senderId,message:text});$('#replyInput').value='';showToast('Đã gửi tin nhắn.')}catch(e){showToast(e.message,'error')}return}appendReply(text);showToast('Đã gửi trả lời trong bản demo.')}

