function switchToLogin(message,email,success=false){$('#registerForm').classList.add('hidden');$('#loginForm').classList.remove('hidden');$('#registerNotice').textContent='';if(email)$('#loginForm [name=email]').value=email;showAuthNotice(message,success)}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();showAuthNotice('');if(!state.firebase){showAuthNotice('Website đang ở chế độ demo. Kết nối Firebase trong Cài đặt hoặc dùng nút trải nghiệm demo.');return}const f=new FormData(e.currentTarget);try{await state.firebase.authMod.signInWithEmailAndPassword(state.firebase.auth,f.get('email'),f.get('password'))}catch(err){showAuthNotice(err.code==='auth/invalid-credential'?'Email hoặc mật khẩu chưa chính xác.':err.message)}});
$('#registerForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form);if(!state.firebase){$('#registerNotice').textContent='Cần kết nối Firebase trước khi tạo tài khoản.';return}state.signingUp=true;try{const {user}=await state.firebase.authMod.createUserWithEmailAndPassword(state.firebase.auth,f.get('email'),f.get('password'));await state.firebase.authMod.updateProfile(user,{displayName:f.get('name')});await state.firebase.storeMod.setDoc(state.firebase.storeMod.doc(state.firebase.db,'users',user.uid),{name:f.get('name'),email:user.email,role:'employee',approved:true,createdAt:state.firebase.storeMod.serverTimestamp()});await state.firebase.authMod.signOut(state.firebase.auth);const email=user.email;form.reset();switchToLogin('Đăng ký thành công. Vui lòng đăng nhập bằng tài khoản vừa tạo.',email,true)}catch(err){if(['auth/email-already-in-use','auth/email-already-exists'].includes(err.code)){switchToLogin('Email này đã được đăng ký. Hãy đăng nhập hoặc chọn “Quên mật khẩu?” nếu bạn quên mật khẩu.',f.get('email'))}else{$('#registerNotice').textContent=err.code==='permission-denied'?'Không thể tạo hồ sơ. Hãy triển khai Firestore Rules mới rồi thử lại.':err.message}}finally{state.signingUp=false}});
$('#showRegister').addEventListener('click',e=>{e.preventDefault();showAuthNotice('');$('#registerNotice').textContent='';$('#loginForm').classList.add('hidden');$('#registerForm').classList.remove('hidden')});$('#showLogin').addEventListener('click',e=>{e.preventDefault();showAuthNotice('');$('#registerNotice').textContent='';$('#registerForm').classList.add('hidden');$('#loginForm').classList.remove('hidden')});
$('.toggle-password').addEventListener('click',e=>{const input=$('input',e.currentTarget.parentElement);input.type=input.type==='password'?'text':'password'});
$('#forgotLink').addEventListener('click',async e=>{e.preventDefault();const email=$('#loginForm [name=email]').value;if(!state.firebase){showAuthNotice('Kết nối Firebase và nhập email để nhận liên kết đặt lại mật khẩu.');return}if(!email){showAuthNotice('Nhập email trước, sau đó bấm Quên mật khẩu.');return}try{await state.firebase.authMod.sendPasswordResetEmail(state.firebase.auth,email);showAuthNotice('Đã gửi liên kết đặt lại mật khẩu nếu email tồn tại.',true)}catch(err){showAuthNotice(err.message)}});
$('#logoutBtn').addEventListener('click',async()=>{if(state.firebase&&state.user?.uid!=='demo')await state.firebase.authMod.signOut(state.firebase.auth);localStorage.removeItem('fbtq_demo_user');signOutToAuth()});

// Navigation and common controls
const pageNames={overview:'Tổng quan',analytics:'Hiệu suất marketing',content:'Tạo content',tasks:'Công việc',automation:'Tự động hoá',inbox:'Chatbot AI',people:'Nhân sự & phân quyền',settings:'Cài đặt hệ thống'};
function navigate(name){if(name==='people'&&!isDirector()){showToast('Chỉ Giám đốc mới có thể quản lý quyền truy cập.','error');return}$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${name}`));$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===name));$('#crumbPage').textContent=pageNames[name]||name;$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show');window.scrollTo({top:0,behavior:'smooth'})}
$$('.nav-item').forEach(el=>el.addEventListener('click',()=>navigate(el.dataset.page)));$$('[data-goto]').forEach(el=>el.addEventListener('click',()=>navigate(el.dataset.goto)));
$('#mobileMenu').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#sidebarScrim').classList.add('show')});$('#sidebarClose').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show')});$('#sidebarScrim').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show')});
$('#themeToggle').addEventListener('click',()=>setTheme(document.body.classList.contains('dark')?'light':'dark'));function setTheme(mode){document.body.classList.toggle('dark',mode==='dark');localStorage.setItem(storeKey(),JSON.stringify({...JSON.parse(localStorage.getItem(storeKey())||'{}'),theme:mode}));$$('[data-theme-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.themeChoice===mode))}
$$('[data-theme-choice]').forEach(b=>b.addEventListener('click',()=>setTheme(b.dataset.themeChoice)));
$('#searchTrigger').addEventListener('click',()=>{$('#searchBox').classList.toggle('hidden');if(!$('#searchBox').classList.contains('hidden'))$('input',$('#searchBox')).focus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#searchBox').classList.add('hidden');closeModal()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchBox').classList.remove('hidden');$('input',$('#searchBox')).focus()}});
$$('[data-setting]').forEach(b=>b.addEventListener('click',()=>selectSetting(b.dataset.setting)));function selectSetting(name){$$('[data-setting]').forEach(b=>b.classList.toggle('selected',b.dataset.setting===name));$$('.setting-section').forEach(s=>s.classList.toggle('selected',s.id===`setting-${name}`))}
$$('.filter-tabs button').forEach(b=>{if(!b.dataset.taskFilter)b.addEventListener('click',()=>{const group=b.parentElement;$$('button',group).forEach(x=>x.classList.remove('selected'));b.classList.add('selected')})});

// Reusable modal
function openModal(title,body,submitText='Lưu',onSubmit=null){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h3>${esc(title)}</h3><button class="modal-close" type="button" aria-label="Đóng">×</button></div><form id="activeModalForm"><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="btn btn-secondary modal-cancel">Huỷ</button>${submitText?`<button type="submit" class="btn btn-primary">${esc(submitText)}</button>`:''}</div></form></section></div>`;$('.modal-close',root).addEventListener('click',closeModal);$('.modal-cancel',root).addEventListener('click',closeModal);$('.modal-backdrop',root).addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});if(onSubmit)$('#activeModalForm',root).addEventListener('submit',async e=>{e.preventDefault();const btn=$('button[type=submit]',e.currentTarget);btn.disabled=true;try{await onSubmit(new FormData(e.currentTarget),e.currentTarget)}catch(err){showToast(err.message||'Có lỗi xảy ra.','error');btn.disabled=false}});setTimeout(()=>$('.modal-fields input, .modal-fields textarea, .modal-fields select',root)?.focus(),50)}
function closeModal(){$('#modalRoot').innerHTML=''}
const fInput=(label,name,placeholder='',type='text',required=true)=>`<label>${esc(label)}<input name="${esc(name)}" type="${type}" placeholder="${esc(placeholder)}" ${required?'required':''}></label>`;
const fSelect=(label,name,options)=>`<label>${esc(label)}<select name="${esc(name)}">${options.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select></label>`;

// Campaign metrics import/export
function formatMetric(raw,index=0){const get=(...keys)=>{for(const key of keys)if(raw[key]!==undefined)return raw[key];const lower=Object.fromEntries(Object.entries(raw).map(([k,v])=>[String(k).toLowerCase().replace(/[ _-]/g,''),v]));for(const key of keys){const normalized=key.toLowerCase().replace(/[ _-]/g,'');if(lower[normalized]!==undefined)return lower[normalized]}return ''};const numeric=(v)=>Number(String(v??'').replace(/[^\d.-]/g,''))||0;return{id:String(get('id','campaignId','campaign_id')||`import-${Date.now()}-${index}`),name:String(get('name','campaign','campaignName','campaign_name')||`Chiến dịch ${index+1}`),account:String(get('account','adAccount','accountName')||'Meta Ads'),platform:String(get('platform','source')||'Facebook'),budget:numeric(get('budget','dailyBudget','lifetimeBudget')),spend:numeric(get('spend','amountSpent','amount_spent','cost')),impressions:numeric(get('impressions','reach')),results:numeric(get('results','conversions','leads','purchases')),roas:numeric(get('roas','returnOnAdSpend'))||Number(get('roas','returnOnAdSpend'))||0,status:String(get('status','delivery')||'Đang chạy')}}
function campaignRows(list){return list.map(c=>`<tr><td><span class="campaign-avatar ${String(c.platform).toLowerCase().includes('google')?'ca-yellow':'ca-blue'}">${esc(c.name.slice(0,1).toUpperCase())}</span><span class="campaign-title"><b>${esc(c.name)}</b><small>${esc(c.account)}</small></span></td><td><span class="platform-pill"><i class="platform-dot ${String(c.platform).toLowerCase().includes('google')?'gg':'fb'}"></i>${esc(c.platform)}</span></td><td>${c.budget?money(c.budget):'—'}</td><td>${money(c.spend)}</td><td>${Number(c.impressions).toLocaleString('vi-VN')}</td><td>${Number(c.results).toLocaleString('vi-VN')}</td><td><b>${Number(c.roas).toFixed(2)}x</b></td><td><span class="status ${String(c.status).toLowerCase().includes('chạy')?'status-live':'status-review'}">● ${esc(c.status)}</span></td></tr>`).join('')}
function renderMetrics(){const live=!!(state.firebase&&state.user?.uid!=='demo');const list=live?state.metrics:[...defaultMetrics,...state.metrics];$('#analyticsTable').innerHTML=campaignRows(list);$('#emptyImport').classList.toggle('hidden',list.length>0);$('#campaignTable').innerHTML=list.slice(0,3).map(c=>`<tr><td><span class="campaign-avatar ca-blue">${esc(c.name[0])}</span><span class="campaign-title"><b>${esc(c.name)}</b><small>${esc(c.account)}</small></span></td><td><span class="platform-pill"><i class="platform-dot fb"></i>${esc(c.platform)}</span></td><td>${money(c.spend)}</td><td><b>${Number(c.roas).toFixed(2)}x</b></td><td><span class="status status-live">● ${esc(c.status)}</span></td></tr>`).join('');if(list.length){const spend=list.reduce((n,x)=>n+(Number(x.spend)||0),0),impressions=list.reduce((n,x)=>n+(Number(x.impressions)||0),0),results=list.reduce((n,x)=>n+(Number(x.results)||0),0),roas=spend?list.reduce((n,x)=>n+(Number(x.spend)||0)*(Number(x.roas)||0),0)/spend:0;const stats=$$('.analytics-stats .stat-value');if(stats[0])stats[0].innerHTML=`₫${(spend/1e6).toLocaleString('vi-VN',{maximumFractionDigits:2})}<span class="unit">tr</span>`;if(stats[1])stats[1].innerHTML=`${(impressions/1e6).toLocaleString('vi-VN',{maximumFractionDigits:2})}<span class="unit">tr</span>`;if(stats[2]){const cpr=results?spend/results:0;stats[2].innerHTML=`₫${(cpr/1000).toLocaleString('vi-VN',{maximumFractionDigits:1})}<span class="unit">k / KQ</span>`}if(stats[3])stats[3].innerHTML=`${roas.toLocaleString('vi-VN',{maximumFractionDigits:2})}<span class="unit">x</span>`}else if(live){$$('.analytics-stats .stat-value').forEach(x=>x.textContent='—')}}
function importCampaignData(value){let parsed=value;if(typeof value==='string'){const trimmed=value.trim();if(trimmed.startsWith('[')||trimmed.startsWith('{'))parsed=JSON.parse(trimmed);else parsed=parseCsv(trimmed)}const rows=Array.isArray(parsed)?parsed:(parsed.campaigns||parsed.data||parsed.rows||[parsed]);if(!Array.isArray(rows)||!rows.length)throw new Error('Không tìm thấy dòng chiến dịch trong dữ liệu.');const normalized=rows.map(formatMetric);state.metrics=[...state.metrics,...normalized];saveLocal();renderMetrics();closeModal();showToast(`Đã nhập ${rows.length} chiến dịch.`);if(state.firebase)normalized.map(row=>saveRecord('campaigns',row,row.id).catch(console.error))}
function parseCsv(text){const lines=text.split(/\r?\n/).filter(Boolean);if(lines.length<2)throw new Error('CSV cần có dòng tiêu đề và ít nhất một chiến dịch.');const headers=lines.shift().split(',').map(s=>s.trim());return lines.map(line=>{const vals=line.split(',');return Object.fromEntries(headers.map((h,i)=>[h,(vals[i]||'').trim()]))})}
function showImportModal(){openModal('Nhập chỉ số quảng cáo',`<p>Dán dữ liệu JSON đã sao chép từ Ads Clipper hoặc chọn JSON/CSV. Các chỉ số sẽ được thêm vào danh sách chiến dịch.</p><div class="modal-fields"><label>Dữ liệu JSON hoặc CSV<textarea name="metrics" placeholder='[{"name":"Summer Sale","spend":1245000,"impressions":58200,"results":31,"roas":3.4}]' required></textarea></label><label>Hoặc chọn tệp<input id="modalMetricsFile" type="file" accept=".json,.csv"></label></div>`,'Nhập dữ liệu',async(form)=>{const text=form.get('metrics');importCampaignData(text)});$('#modalMetricsFile')?.addEventListener('change',async e=>{const file=e.target.files[0];if(file)$('textarea[name=metrics]').value=await file.text()})}
$('#importMetrics').addEventListener('click',showImportModal);$('#importEmpty').addEventListener('click',showImportModal);$('#metricsFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{importCampaignData(await file.text())}catch(err){showToast(err.message,'error')}e.target.value=''});
$('#copyGuide').addEventListener('click',async()=>{try{const text=await navigator.clipboard.readText();if(text.trim().startsWith('[')||text.trim().startsWith('{')){showImportModal();$('textarea[name=metrics]')&&($('textarea[name=metrics]').value=text);return}}catch{}openModal('Sao chép từ Meta Ads Manager',`<p>Mở Meta Ads Manager, cài tiện ích <b>FBTQ Ads Clipper</b> trong thư mục extension, rồi chọn “Sao chép chỉ số”. Tiện ích đọc các chiến dịch đang hiển thị và sao chép JSON vào clipboard.</p><div class="setup-callout"><span>▣</span><div><b>Nhập nhanh từ clipboard</b><p>Cấp quyền đọc clipboard cho website, sau đó bấm nút bên dưới. Bạn cũng có thể dán JSON trực tiếp.</p></div></div><div class="modal-fields"><label>Dữ liệu JSON<textarea name="metrics" placeholder='Dán dữ liệu đã sao chép tại đây'></textarea></label></div>`,'Đọc clipboard & nhập',async(form)=>{let txt=form.get('metrics');if(!txt.trim())try{txt=await navigator.clipboard.readText()}catch{throw new Error('Hãy dán dữ liệu JSON vào ô bên trên.')}if(!txt.trim())throw new Error('Clipboard chưa có dữ liệu chiến dịch.');importCampaignData(txt)})});
$('#clearMetrics').addEventListener('click',async()=>{const live=state.firebase&&state.user?.uid!=='demo';if(live&&!isManager())return showToast('Chỉ quản lý mới có thể xoá chiến dịch đã lưu.','error');if(live)try{for(const row of state.metrics)if(row.id)await state.firebase.storeMod.deleteDoc(state.firebase.storeMod.doc(state.firebase.db,'workspaces','fbtq','campaigns',row.id))}catch(e){showToast(e.message,'error');return}state.metrics=[];saveLocal();renderMetrics();showToast('Đã xoá dữ liệu chiến dịch đã nhập.','success')});
$('#exportMetrics').addEventListener('click',()=>downloadFile('fbtq-campaigns.json',JSON.stringify([...defaultMetrics,...state.metrics],null,2),'application/json'));
function downloadFile(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
// Decorative chart bars are deterministically seeded by the day.
const bars=$('#bigBars');for(let i=1;i<=30;i++){const a=24+((i*37)%54),b=35+((i*53)%62);const g=document.createElement('div');g.className='bar-group';g.dataset.label=String(i).padStart(2,'0');g.innerHTML=`<i class="bar spend" style="height:${a}%;animation-delay:${i*12}ms"></i><i class="bar revenue" style="height:${b}%;animation-delay:${i*12+75}ms"></i>`;bars.append(g)}

// AI content studio, saved drafts and manager review flow.
$$('[data-editor-tab]').forEach(b=>b.addEventListener('click',()=>{const tab=b.dataset.editorTab;$$('[data-editor-tab]').forEach(x=>x.classList.toggle('selected',x===b));$('#createTab').classList.toggle('hidden',tab!=='create');$('#templatesTab').classList.toggle('hidden',tab!=='templates');$('#draftsTab').classList.toggle('hidden',tab!=='drafts')}));
$$('.template-card').forEach(b=>b.addEventListener('click',()=>{$('#contentPrompt').value=b.dataset.prompt;$$('[data-editor-tab]').find(x=>x.dataset.editorTab==='create').click();$('#contentPrompt').focus()}));
$$('.model-choice').forEach(b=>b.addEventListener('click',()=>{$$('.model-choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('input',b).checked=true}));
function renderDrafts(){$('#draftCount').textContent=state.drafts.length;$('#draftList').innerHTML=state.drafts.length?state.drafts.map(d=>`<div class="draft-row"><span class="template-icon ti-purple">▤</span><div><b>${esc(d.title)}</b><small>${esc(d.updated||'Vừa lưu')} · ${esc(d.text.slice(0,72))}${d.text.length>72?'…':''}</small></div><button data-open-draft="${esc(d.id)}">Mở</button><button data-delete-draft="${esc(d.id)}">Xoá</button></div>`).join(''):'<p class="muted">Chưa có bản nháp nào.</p>';$$('[data-open-draft]').forEach(b=>b.addEventListener('click',()=>{const d=state.drafts.find(x=>x.id===b.dataset.openDraft);if(d)showGenerated(d.title,d.text)}));$$('[data-delete-draft]').forEach(b=>b.addEventListener('click',()=>{state.drafts=state.drafts.filter(x=>x.id!==b.dataset.deleteDraft);saveLocal();renderDrafts()}))}
function showGenerated(title,text){$('#resultPanel').innerHTML=`<div class="result-generated"><div class="generated-head"><b>${esc(title)}</b><span class="status status-neutral">BẢN NHÁP AI</span></div><div class="generated-content" contenteditable="true">${esc(text)}</div><div class="generated-actions"><button class="btn btn-secondary" id="saveDraft">▤ Lưu nháp</button><button class="btn btn-secondary" id="copyContent">▣ Sao chép</button><button class="btn btn-primary manager-review">⇧ Gửi quản lý duyệt</button></div></div>`;$('#saveDraft').addEventListener('click',()=>saveDraft(title,$('.generated-content').innerText));$('#copyContent').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('.generated-content').innerText);showToast('Đã sao chép nội dung.')}catch{showToast('Trình duyệt chưa cho phép clipboard.','error')}});$('.manager-review').addEventListener('click',async()=>{if(state.firebase)await saveRecord('contentReviews',{title,text:$('.generated-content').innerText,status:'pending'});showToast('Đã gửi nội dung vào hàng chờ quản lý duyệt.');$('.manager-review').textContent='✓ Đã gửi duyệt';$('.manager-review').disabled=true})}
async function saveDraft(title,text){const draft={id:crypto.randomUUID(),title,text,updated:new Date().toLocaleDateString('vi-VN',{day:'2-digit',month:'short',year:'numeric'}),createdBy:state.user?.uid||null};state.drafts.unshift(draft);saveLocal();renderDrafts();if(state.firebase)try{await saveRecord('drafts',draft,draft.id)}catch(e){showToast(e.message,'error');return}showToast('Đã lưu bản nháp.')}
const contentQueueButton=$('.approval-queue .text-button');const contentQueueControl=contentQueueButton.cloneNode(true);contentQueueControl.removeAttribute('data-goto');contentQueueButton.replaceWith(contentQueueControl);contentQueueControl.addEventListener('click',openContentQueue);
async function openContentQueue(){if(!isManager())return showToast('Chỉ quản lý mới có thể duyệt nội dung.','error');if(state.firebase){try{const [a,b]=await Promise.all([state.firebase.storeMod.getDocs(state.firebase.storeMod.collection(state.firebase.db,'workspaces','fbtq','contentReviews')),state.firebase.storeMod.getDocs(state.firebase.storeMod.collection(state.firebase.db,'workspaces','fbtq','contentTemplates'))]);state.reviews=a.docs.map(d=>({id:d.id,...d.data()}));state.templates=b.docs.map(d=>({id:d.id,...d.data()}))}catch(e){return showToast(e.message,'error')}}const items=[...state.reviews.map(x=>({...x,kind:'contentReviews'})),...state.templates.filter(x=>x.status==='pending').map(x=>({...x,kind:'contentTemplates'}))].filter(x=>x.status==='pending');const rows=items.length?items.map(x=>`<div class="request-row"><span class="template-icon ti-purple">✳</span><div><b>${esc(x.title||'Nội dung đề xuất')}</b><small>${esc(x.kind==='contentTemplates'?'Mẫu nội dung':'Nội dung AI')} · ${esc(x.text||x.prompt||'').slice(0,90)}</small></div><button class="approve-btn" data-review="approve" data-kind="${esc(x.kind)}" data-id="${esc(x.id)}">Duyệt</button><button class="reject-btn" data-review="reject" data-kind="${esc(x.kind)}" data-id="${esc(x.id)}">Từ chối</button></div>`).join(''):'<p class="muted">Hiện chưa có nội dung nào chờ duyệt.</p>';openModal('Hàng chờ duyệt nội dung',`<p>Quản lý xem nội dung nhân viên gửi trước khi dùng mẫu hoặc đăng chiến dịch.</p>${rows}`,'',null);$$('[data-review]').forEach(btn=>btn.addEventListener('click',async()=>{const kind=btn.dataset.kind,id=btn.dataset.id,status=btn.dataset.review==='approve'?'approved':'rejected';try{if(state.firebase){const original=kind==='contentReviews'?state.reviews.find(x=>x.id===id):state.templates.find(x=>x.id===id);await saveRecord(kind,{...original,status,reviewedBy:state.user.uid,reviewedAt:new Date().toISOString()},id)}if(kind==='contentReviews')state.reviews=state.reviews.map(x=>x.id===id?{...x,status}:x);else state.templates=state.templates.map(x=>x.id===id?{...x,status}:x);btn.closest('.request-row').remove();showToast(status==='approved'?'Đã duyệt nội dung.':'Đã từ chối nội dung.');if(!$$('[data-review]').length){$('.modal-body').insertAdjacentHTML('beforeend','<p class="muted">Đã xử lý hết hàng chờ.</p>')}}catch(e){showToast(e.message,'error')}}))}
$('#generateContent').addEventListener('click',async()=>{const prompt=$('#contentPrompt').value.trim();if(!prompt){showToast('Nhập ý tưởng hoặc prompt trước khi tạo nội dung.','error');$('#contentPrompt').focus();return}const button=$('#generateContent'),old=button.innerHTML;button.disabled=true;button.innerHTML='✦ Đang viết…';try{const platform=$('#contentPlatform').value,tone=$('#contentTone').value,length=$('#contentLength').value,model=$('input[name=aiModel]:checked').value;let text,title=prompt.slice(0,42)+(prompt.length>42?'…':'');if(state.firebase){const result=await callFunction('generateContent',{prompt,platform,tone,length,model});text=result.content}else{text=`${prompt}\n\n${platform} · ${tone}\n\n${prompt.split(/[.!?]/)[0]} — câu chuyện của bạn xứng đáng được kể theo cách riêng. ✨\n\nKhám phá ngay hôm nay để nhận ưu đãi dành riêng cho cộng đồng FBTQ. Nhắn tin cho chúng mình để được tư vấn nhé!\n\n#FBTQ #SongChat #LuaChonCuaBan`;showToast('Nội dung minh hoạ. Kết nối Firebase Functions để gọi mô hình AI thật.')}showGenerated(title,text)}catch(err){showToast(err.message,'error')}finally{button.disabled=false;button.innerHTML=old}});
$('#openDrafts').addEventListener('click',()=>{navigate('content');$$('[data-editor-tab]').find(x=>x.dataset.editorTab==='drafts').click()});$('#addTemplate').addEventListener('click',()=>{openModal('Đề xuất mẫu nội dung',`<div class="modal-fields">${fInput('Tên mẫu','title','Ví dụ: Ra mắt bộ sưu tập')}${fSelect('Nền tảng','platform',[['Facebook','Facebook'],['Instagram','Instagram'],['TikTok','TikTok'],['Email','Email marketing']])}<label>Nội dung mẫu<textarea name="prompt" placeholder="Mô tả prompt mẫu..."></textarea></label></div>`,'Gửi quản lý duyệt',async f=>{if(state.firebase)await saveRecord('contentTemplates',{title:f.get('title'),platform:f.get('platform'),prompt:f.get('prompt'),status:'pending'});closeModal();showToast('Đã gửi đề xuất mẫu tới quản lý.')})});

// Tasks: only management roles can create or assign. Staff can update own task status.
const taskColumns=[['todo','Chưa bắt đầu'],['doing','Đang làm'],['done','Hoàn thành']];
function taskDate(d){if(!d)return'Chưa đặt hạn';const date=new Date(d);return date.toLocaleDateString('vi-VN',{day:'2-digit',month:'short'})+' · '+date.toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}
function renderTasks(filter='all'){const assignee=$('#taskAssigneeFilter')?.value||'all';$('#taskBoard').innerHTML=taskColumns.map(([status,title])=>{let tasks=state.tasks.filter(t=>t.status===status&&(filter==='all'||filter===status)&&(assignee==='all'||t.assignee===assignee));return`<section class="task-column"><div class="task-column-head"><b>${title}</b><span class="column-count">${tasks.length}</span></div><div class="task-column-list">${tasks.map(t=>`<article class="task-card"><div class="task-card-top"><span class="task-tag">${esc(t.tag)}</span>${t.priority==='Cao'?'<span class="priority-label">● Ưu tiên cao</span>':''}</div><h4>${esc(t.title)}</h4><p>${esc(t.description)}</p><div class="task-card-foot"><span class="task-assignee"><i class="avatar avatar-${esc(t.tone||'blue')}">${esc(t.initials||'??')}</i>${esc(t.assignee)}</span><span class="${status!=='done'&&new Date(t.due)<new Date()?'due-urgent':''}">◷ ${esc(taskDate(t.due))}</span></div><div class="task-card-foot"><span>Giao ${esc(taskDate(t.createdAt||'2026-11-03T09:00'))}</span><select data-task-status="${esc(t.id)}" aria-label="Cập nhật trạng thái">${taskColumns.map(([v,l])=>`<option value="${v}" ${v===status?'selected':''}>${l}</option>`).join('')}</select></div></article>`).join('')||'<div class="muted" style="font-size:9px;padding:10px 2px">Không có công việc</div>'}</div></section>`}).join('');$$('[data-task-status]').forEach(sel=>sel.addEventListener('change',async()=>{const task=state.tasks.find(t=>t.id===sel.dataset.taskStatus);if(!task)return;if(!isManager()&&task.assigneeUid!==state.user?.uid&&task.assignee!==state.user?.name){showToast('Bạn chỉ có thể cập nhật công việc được giao cho mình.','error');sel.value=task.status;return}task.status=sel.value;saveLocal();if(state.firebase)try{await saveRecord('tasks',task,task.id)}catch(e){showToast(e.message,'error');return}renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all');$('#taskNavCount').textContent=state.tasks.filter(t=>t.status!=='done').length;showToast('Đã cập nhật trạng thái công việc.')}))}
$('#taskAssigneeFilter').addEventListener('change',()=>renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all'));
$$('[data-task-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-task-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderTasks(b.dataset.taskFilter)}));
$('#newTaskBtn').addEventListener('click',()=>{if(!isManager())return showToast('Bạn không có quyền giao công việc.','error');openModal('Giao công việc mới',`<div class="modal-fields">${fInput('Tên công việc','title','Ví dụ: Hoàn thiện báo cáo tuần')}${fInput('Mô tả','description','Mục tiêu và yêu cầu bàn giao', 'text',false)}${fSelect('Người nhận','assignee',state.members.map(m=>[m.uid,m.name]))}${fSelect('Mức ưu tiên','priority',[['Bình thường','Bình thường'],['Cao','Ưu tiên cao'],['Thấp','Thấp']])}<label>Hạn hoàn thành<input type="datetime-local" name="due" required></label>${fSelect('Phân loại','tag',[['Quảng cáo','Quảng cáo'],['Nội dung','Nội dung'],['Báo cáo','Báo cáo'],['Chatbot','Chatbot'],['Thiết kế','Thiết kế'],['Website','Website']])}</div>`,'Giao việc',async f=>{const member=state.members.find(m=>m.uid===f.get('assignee'));const assignee=member?.name||f.get('assignee'),initials=member?.initials||assignee.split(' ').map(x=>x[0]).join('').toUpperCase();const task={id:crypto.randomUUID(),title:f.get('title'),description:f.get('description'),assignee,assigneeUid:member?.uid||'',initials,tone:member?.tone||'blue',status:'todo',due:f.get('due'),priority:f.get('priority'),tag:f.get('tag'),createdAt:new Date().toISOString()};state.tasks.unshift(task);saveLocal();if(state.firebase)await saveRecord('tasks',task,task.id);closeModal();renderTasks();showToast('Đã giao công việc.')})});

// Reports, requests and invoice generation.
$('#dailyReportBtn').addEventListener('click',()=>openModal('Báo cáo quảng cáo hàng ngày',`<p>Điền chỉ số của chiến dịch trong ngày. Báo cáo sẽ được lưu để quản lý theo dõi.</p><div class="modal-fields">${fInput('Chiến dịch','campaign','Tên chiến dịch')}${fInput('Chi tiêu (₫)','spend','Ví dụ: 1240000','number')}${fInput('Hiển thị','impressions','Ví dụ: 28400','number')}${fInput('Kết quả / đơn hàng','results','Ví dụ: 28','number')}<label>Ghi chú<textarea name="note" placeholder="Nhận xét kết quả, khó khăn hoặc đề xuất..."></textarea></label></div>`,'Nộp báo cáo',async f=>{const report={campaign:f.get('campaign'),spend:Number(f.get('spend')),impressions:Number(f.get('impressions')),results:Number(f.get('results')),note:f.get('note'),employee:state.user?.name,submittedAt:new Date().toISOString()};if(state.firebase)await saveRecord('dailyReports',report);closeModal();showToast('Đã nộp báo cáo quảng cáo hôm nay.') }));
$('#invoiceBtn').addEventListener('click',()=>{if(!isManager())return showToast('Chỉ quản lý mới có thể tạo hoá đơn.','error');openModal('Tạo hoá đơn',`<p>Hoá đơn sẽ được tạo thành tệp HTML để mở, in hoặc lưu thành PDF từ trình duyệt.</p><div class="modal-fields">${fInput('Tên khách hàng','customer','Họ tên / tên công ty')}${fInput('Mã số thuế (nếu có)','taxId','MST', 'text',false)}${fInput('Dịch vụ / sản phẩm','item','Tên dịch vụ')}${fInput('Số lượng','quantity','1','number')}${fInput('Đơn giá (₫)','price','Ví dụ: 5000000','number')}<label>Ghi chú<textarea name="note" placeholder="Điều khoản thanh toán..."></textarea></label></div>`,'Tạo tệp hoá đơn',async f=>{const qty=Number(f.get('quantity'))||1,price=Number(f.get('price'))||0,total=qty*price;const html=`<!doctype html><html lang="vi"><meta charset="utf-8"><title>Hoá đơn FBTQ</title><style>body{font:14px Arial;color:#233;padding:48px;max-width:800px;margin:auto}h1{color:#3575ed}table{width:100%;border-collapse:collapse;margin:25px 0}td,th{border:1px solid #ddd;padding:12px;text-align:left}.total{text-align:right;font-size:20px;font-weight:bold}.muted{color:#778}</style><h1>HOÁ ĐƠN</h1><p>Marketing Ai FBTQ · Ngày ${new Date().toLocaleDateString('vi-VN')}</p><hr><p><b>Khách hàng:</b> ${esc(f.get('customer'))}<br><b>Mã số thuế:</b> ${esc(f.get('taxId')||'—')}</p><table><tr><th>Dịch vụ / sản phẩm</th><th>Số lượng</th><th>Đơn giá</th><th>Thành tiền</th></tr><tr><td>${esc(f.get('item'))}</td><td>${qty}</td><td>${money(price)}</td><td>${money(total)}</td></tr></table><p class="total">Tổng cộng: ${money(total)}</p><p>${esc(f.get('note')||'')}</p><p style="margin-top:70px">Đại diện FBTQ ____________________</p></html>`;downloadFile(`hoa-don-fbtq-${Date.now()}.html`,html,'text/html');if(state.firebase)await saveRecord('invoices',{customer:f.get('customer'),item:f.get('item'),quantity:qty,price,total,createdAt:new Date().toISOString()});closeModal();showToast('Đã tải mẫu hoá đơn HTML. Mở tệp và chọn In → Lưu thành PDF.')})});
async function openRequests(){if(!isManager())return showToast('Chỉ quản lý mới có thể duyệt đơn.','error');if(state.firebase){try{const snap=await state.firebase.storeMod.getDocs(state.firebase.storeMod.collection(state.firebase.db,'workspaces','fbtq','requests'));state.requests=snap.docs.map(d=>({id:d.id,...d.data()}))}catch(e){return showToast(e.message,'error')}}const pending=state.requests.filter(r=>r.status==='pending');const rows=pending.length?pending.map(r=>`<div class="request-row"><span class="avatar avatar-peach">${esc((r.employee||'NV').split(/\s+/).map(x=>x[0]).join('').slice(-2))}</span><div><b>${esc(r.employee||'Nhân viên')} · ${esc(r.type||'Yêu cầu')}</b><small>${esc(r.date||'')} · ${esc(r.description||'')}</small></div><button class="approve-btn" data-request="approve" data-id="${esc(r.id)}">Duyệt</button><button class="reject-btn" data-request="reject" data-id="${esc(r.id)}">Từ chối</button></div>`).join(''):'<p class="muted">Không có đơn nào đang chờ.</p>';openModal('Đơn cần xử lý',`<p>Yêu cầu nhân viên chờ quản lý xem xét.</p>${rows}`,'',null);$$('[data-request]').forEach(b=>b.addEventListener('click',async()=>{const item=state.requests.find(x=>x.id===b.dataset.id);if(!item)return;const status=b.dataset.request==='approve'?'approved':'rejected';try{if(state.firebase)await saveRecord('requests',{...item,status,reviewedBy:state.user.uid,reviewedAt:new Date().toISOString()},item.id);item.status=status;b.parentElement.style.opacity='.45';b.parentElement.querySelectorAll('button').forEach(x=>x.disabled=true);b.textContent=status==='approved'?'Đã duyệt':'Đã từ chối';showToast(status==='approved'?'Đã duyệt đơn.':'Đã từ chối đơn.')}catch(e){showToast(e.message,'error')}}))}
$('#reviewRequests').addEventListener('click',openRequests);
const requestButton=document.createElement('button');requestButton.className='btn btn-secondary';requestButton.textContent='＋ Gửi yêu cầu';requestButton.addEventListener('click',()=>openModal('Gửi yêu cầu',`<div class="modal-fields">${fSelect('Loại yêu cầu','type',[['Xin nghỉ phép','Xin nghỉ phép'],['Làm việc từ xa','Làm việc từ xa'],['Đề xuất công cụ','Đề xuất công cụ']])}${fInput('Ngày áp dụng','date','', 'date')}${fInput('Mô tả','description','Lý do hoặc thông tin đề xuất')}</div>`,'Gửi quản lý',async f=>{const item={type:f.get('type'),date:f.get('date'),description:f.get('description'),employee:state.user?.name,status:'pending',submittedAt:new Date().toISOString()};if(state.firebase)await saveRecord('requests',item);state.requests.unshift({...item,id:crypto.randomUUID()});closeModal();showToast('Đã gửi yêu cầu cho quản lý.') }));$('#page-automation .page-heading').append(requestButton);

// Chatbot demo and integrations.
$('#botToggle').addEventListener('click',e=>e.currentTarget.classList.toggle('on'));
function appendReply(text){const msg=document.createElement('div');msg.className='message';msg.style.cssText='margin:12px 0 0 auto;background:#edf3ff;color:#536c94;border-radius:9px 3px 9px 9px';msg.textContent=text;const time=document.createElement('small');time.textContent=new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'});msg.append(time);$('#chatBody').append(msg);$('#replyInput').value='';$('#chatBody').scrollTop=$('#chatBody').scrollHeight}
$('#sendSuggestion').addEventListener('click',()=>sendChatReply($('.ai-suggestion p').textContent));$('#editSuggestion').addEventListener('click',()=>{const p=$('.ai-suggestion p');p.contentEditable='true';p.focus();p.style.outline='1px solid #9ab9f5'});$('#regenerateReply').addEventListener('click',()=>showToast('Kết nối Fanpage đã đăng ký webhook để tạo gợi ý thật.'));
$('#sendReply').addEventListener('click',async()=>{const text=$('#replyInput').value.trim();if(!text)return;await sendChatReply(text)});$('#replyInput').addEventListener('keydown',e=>{if(e.key==='Enter')$('#sendReply').click()});
function editScripts(){if(!isManager())return showToast('Chỉ quản lý mới có thể chỉnh kịch bản.','error');const content=state.scripts.map((s,i)=>`<div class="draft-row"><span class="template-icon ti-blue">▧</span><div><b>${esc(s.title)}</b><small>${esc(s.text)}</small>${s.image?`<small>✓ Đã đính kèm hình ảnh</small>`:''}</div><button data-edit-script="${i}">Sửa</button></div>`).join('');openModal('Kịch bản phản hồi',`<p>Quản lý câu trả lời nhanh đã được duyệt. Có thể gắn kịch bản vào Fanpage.</p><div class="draft-list">${content||'Chưa có kịch bản.'}</div><button type="button" class="btn btn-secondary" id="newScript" style="margin-top:12px">＋ Thêm kịch bản</button>`,'',null);$('#newScript').addEventListener('click',()=>editScriptForm());$$('[data-edit-script]').forEach(b=>b.addEventListener('click',()=>editScriptForm(Number(b.dataset.editScript))))}
function editScriptForm(index=null){const item=index===null?{title:'',text:''}:state.scripts[index];openModal(index===null?'Thêm kịch bản':'Sửa kịch bản',`<div class="modal-fields">${fInput('Tên kịch bản','title','Ví dụ: Chào khách mới')}<label>Nội dung trả lời<textarea name="text" required>${esc(item.text)}</textarea></label><label>Hình ảnh (tuỳ chọn)<input type="file" name="imageFile" accept="image/*"></label><img id="scriptPreview" class="${item.image?'':'hidden'}" src="${esc(item.image||'')}" style="max-width:100px;border-radius:7px"></div>`,'Lưu kịch bản',async f=>{const file=$('[name=imageFile]').files[0];let image=item.image||'';if(file)image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const next={title:f.get('title'),text:f.get('text'),image};if(index===null)state.scripts.push(next);else state.scripts[index]=next;saveLocal();if(state.firebase)await saveRecord('settings',{scripts:state.scripts},'bot');closeModal();editScripts();showToast('Đã lưu kịch bản.')});$('[name=imageFile]')?.addEventListener('change',e=>{const f=e.target.files[0];if(f){const img=$('#scriptPreview');img.src=URL.createObjectURL(f);img.classList.remove('hidden')}})}
function editBanned(){if(!isManager())return showToast('Chỉ quản lý mới có thể chỉnh từ khoá cấm.','error');openModal('Từ khoá cấm',`<p>Mỗi dòng là một cụm từ. AI sẽ tránh sử dụng các cụm từ này trong gợi ý phản hồi.</p><div class="modal-fields"><label>Từ khoá<textarea name="words">${esc(state.banned.join('\n'))}</textarea></label></div>`,'Lưu từ khoá',async f=>{state.banned=f.get('words').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);saveLocal();if(state.firebase)await saveRecord('settings',{banned:state.banned},'bot');$('#bannedSummary').textContent=`${state.banned.length} từ khoá · thay thế bằng phản hồi an toàn`;closeModal();showToast('Đã cập nhật danh sách từ khoá.')})}
$('#manageScripts').addEventListener('click',editScripts);$('#editScripts').addEventListener('click',editScripts);$('#manageBanned').addEventListener('click',editBanned);$('#editBanned').addEventListener('click',editBanned);
function connectPage(){if(!state.firebase){openModal('Kết nối Fanpage',`<p>Fanpage mẫu trong bản demo không kết nối Facebook thật. Kết nối thật cần Firebase, Meta App được duyệt, HTTPS webhook và Page Access Token. Không nhập token trong chế độ demo.</p><div class="setup-callout"><span>ⓘ</span><div><b>Đang chạy với hội thoại minh hoạ</b><p>Kết nối Firebase trước, sau đó thiết lập Meta App và webhook theo README.</p></div></div>`,'Đóng',()=>closeModal());return}openModal('Kết nối Fanpage',`<p>Nhập token Page lấy từ Meta Business. Token sẽ được gửi đến Cloud Function qua HTTPS và mã hoá trước khi lưu.</p><div class="modal-fields">${fInput('Tên Fanpage','pageName','FBTQ Fashion')}${fInput('Facebook Page ID','pageId','Ví dụ: 123456789')}${fInput('Page Access Token','pageToken','Page token','password')}${fSelect('Mô hình AI','model',[['gemini','Gemini'],['openai','ChatGPT']])}</div>`,'Kết nối an toàn',async f=>{const result=await callFunction('connectFacebookPage',{pageName:f.get('pageName'),pageId:f.get('pageId'),pageToken:f.get('pageToken'),model:f.get('model')});closeModal();showToast(result.message||'Đã kết nối Fanpage.')})}
$('#connectPage').addEventListener('click',connectPage);$('#settingsConnectPage').addEventListener('click',connectPage);$('#addPageInline').addEventListener('click',connectPage);

// Access control and user invitations.
$('#inviteUser').addEventListener('click',()=>{if(!isDirector())return showToast('Chỉ Giám đốc mới có thể mời thành viên.','error');openModal('Mời thành viên',`<p>Gửi lời mời để thành viên đăng ký bằng email công ty. Phân quyền có thể thay đổi sau khi tài khoản được xác minh.</p><div class="modal-fields">${fInput('Email công việc','email','ten@fbtq.vn','email')}${fSelect('Vai trò dự kiến','role',Object.entries(ROLE_NAMES).map(([k,v])=>[k,v]))}${fSelect('Phòng ban','department',[['Marketing','Marketing'],['Kinh doanh','Kinh doanh'],['Vận hành','Vận hành']])}</div>`,'Tạo lời mời',async f=>{const invite={email:f.get('email'),role:f.get('role'),department:f.get('department'),status:'invited',invitedBy:state.user?.uid};if(state.firebase)await saveRecord('invitations',invite);closeModal();showToast('Đã tạo lời mời. Chia sẻ liên kết đăng ký với thành viên.')})});
$('#editPermissions').addEventListener('click',()=>{if(!isDirector())return showToast('Chỉ Giám đốc mới có thể chỉnh phân quyền.','error');openModal('Phân quyền & vai trò',`<p>Vai trò có hiệu lực bảo mật sau khi quản trị viên gán custom claims cho người dùng bằng Cloud Function.</p><div class="modal-fields">${fInput('Email tài khoản','email','ten@fbtq.vn','email')}${fSelect('Vai trò mới','role',Object.entries(ROLE_NAMES).map(([k,v])=>[k,v]))}</div>`,'Cập nhật quyền',async f=>{try{await callFunction('setUserRole',{email:f.get('email'),role:f.get('role')});closeModal();showToast('Đã cập nhật vai trò. Người dùng cần đăng nhập lại.')}catch(e){showToast(e.message||'Không thể cập nhật vai trò.','error')}})});
$('#metaConnect').addEventListener('click',()=>{navigate('settings');selectSetting('chatbot');showToast('Thiết lập Meta App trong mục Chatbot & Fanpage.')});

// Firebase and model settings.
$('#saveFirebase').addEventListener('click',async()=>{const c=configFromInputs();if(!validConfig(c)){showToast('Hãy điền đủ Firebase API Key, Auth Domain, Project ID và App ID.','error');return}localStorage.setItem('fbtq_firebase_config',JSON.stringify(c));const ok=await firebaseInit(c,true);if(ok&&window.location.protocol==='file:')showToast('Mở website qua HTTPS để Firebase Auth hoạt động.','error')});
$('#disconnectFirebase').addEventListener('click',async()=>{localStorage.removeItem('fbtq_firebase_config');if(state.firebase)await state.firebase.authMod.signOut(state.firebase.auth);state.firebase=null;$('#firebaseIndicator').textContent='● Chưa kết nối';$('#firebaseIndicator').classList.remove('connected');$('#firebaseStatus').textContent='● Chế độ bản demo';$('#firebaseStatus').className='status status-review';showToast('Đã chuyển về chế độ demo.')});
$('#saveAiSettings').addEventListener('click',async()=>{if(!isManager())return showToast('Chỉ quản lý mới có thể cấu hình mô hình AI.','error');const config={defaultModel:$('#defaultModel').value,brandVoice:$('#brandVoice').value};localStorage.setItem('fbtq_default_model',config.defaultModel);localStorage.setItem('fbtq_brand_voice',config.brandVoice);if(state.firebase)try{await saveRecord('settings',config,'bot')}catch(e){showToast(e.message,'error');return}const radio=$(`input[name="aiModel"][value="${config.defaultModel}"]`);if(radio){radio.checked=true;$$('.model-choice').forEach(x=>x.classList.toggle('selected',$('input',x)===radio))}$('#aiConfigStatus').textContent='Đã lưu lựa chọn mô hình. API keys được quản lý trên Firebase Functions.';showToast('Đã lưu lựa chọn mô hình.')});
$('#enableAutoReply').addEventListener('change',e=>showToast(e.target.checked?'Đã bật chế độ AI đề xuất. Nhân viên cần xác nhận trước khi gửi.':'Đã tắt AI đề xuất.'));

// Small utilities and initial setup.
$('#notificationBtn').addEventListener('click',()=>showToast('Bạn đã cập nhật các thông báo mới nhất.'));
$('#topProfile').addEventListener('click',()=>showToast(`${state.user?.name||'Minh Anh'} · ${roleName(state.role)}`));
$('#copyGuide').setAttribute('aria-label','Hướng dẫn sao chép chỉ số Facebook Ads');
const savedFirebase=getSavedFirebaseConfig()||window.FBTQ_FIREBASE_CONFIG;if(validConfig(savedFirebase)){['apiKey','authDomain','projectId','appId'].forEach(k=>{const el=$('#fb'+k[0].toUpperCase()+k.slice(1));if(el)el.value=savedFirebase[k]});firebaseInit(savedFirebase)}
$('#defaultModel').value=localStorage.getItem('fbtq_default_model')||'gemini';$('#brandVoice').value=localStorage.getItem('fbtq_brand_voice')||'';const bootModel=$('#defaultModel').value,bootRadio=$(`input[name="aiModel"][value="${bootModel}"]`);if(bootRadio){bootRadio.checked=true;$$('.model-choice').forEach(x=>x.classList.toggle('selected',$('input',x)===bootRadio))}
if(localStorage.getItem('fbtq_demo_user')==='1'){state.user={...DEMO_USER,uid:'demo'};state.role='director';enterApp()}
